#!/usr/bin/env python3
"""Regenerates docs/actions.md from the actions the app registers (--list-actions)."""
from __future__ import annotations

import sys
import tempfile
from pathlib import Path

sys.path.insert(0, str(Path(__file__).resolve().parent))
import ahk  # noqa: E402

HEADER = """# Action reference

<!-- Generated by tools/gen_docs.py from `src/Main.ahk --list-actions`. Do not edit by hand. -->

Actions are what bindings, tray items, and gestures run. Reference one by id;
pass `args` as a JSON array in the order listed under **Arguments**
(`[name]` means optional). Plugins can register more actions; see
[plugins.md](plugins.md).

"""


def render(actions: list[dict]) -> str:
    by_module: dict[str, list[dict]] = {}
    for a in actions:
        by_module.setdefault(a["module"] or "other", []).append(a)
    out = [HEADER]
    for module in sorted(by_module):
        out.append(f"## {module}\n\n| Action | Arguments | Description |\n| --- | --- | --- |\n")
        for a in sorted(by_module[module], key=lambda x: x["id"].lower()):
            params = a["params"] or ""
            out.append(f"| `{a['id']}` | {params} | {a['description']} |\n")
        out.append("\n")
    return "".join(out).rstrip("\n") + "\n"


def main() -> int:
    import test

    with tempfile.TemporaryDirectory() as d:
        actions = test.list_actions(d)
    path = ahk.REPO / "docs" / "actions.md"
    path.write_text(render(actions), encoding="utf-8", newline="\n")
    print(f"wrote {path.relative_to(ahk.REPO)} ({len(actions)} actions)")
    return 0


if __name__ == "__main__":
    sys.exit(main())
